using Microsoft.EntityFrameworkCore;

namespace Contoso.Portfolio.Tests;

/// <summary>Real SQLite database files (one per test), real SQL generated by EF Core 10.</summary>
public sealed class DatabaseTests : IAsyncLifetime
{
    private readonly string _path = Path.Combine(Path.GetTempPath(), $"portfolio-test-{Guid.NewGuid():N}.db");
    private readonly List<string> _sql = [];
    private PortfolioDb _db = null!;

    public async Task InitializeAsync() => _db = await PortfolioDb.CreateFreshAsync(_path, _sql.Add);

    public async Task DisposeAsync()
    {
        await _db.DisposeAsync();
        Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
        File.Delete(_path);
    }

    private string LastSql => _sql.LastOrDefault() ?? "";

    [Fact]
    public async Task IQueryable_filters_in_SQL()
    {
        var result = await Queries.AtLeast(_db.Requests, 50_000m).ToListAsync();

        Assert.Equal(5, result.Count);
        Assert.Contains("WHERE ef_compare(\"r\".\"Budget\", @threshold) >= 0", LastSql, StringComparison.Ordinal);
        Assert.Equal(5, _db.ChangeTracker.Entries().Count());
    }

    [Fact]
    public void Gotcha_IEnumerable_parameter_reads_the_whole_table_silently()
    {
        var result = Queries.AtLeast((IEnumerable<ProjectRequest>)_db.Requests, 50_000m).ToList();

        Assert.Equal(5, result.Count);                                   // same answer...
        Assert.DoesNotContain("WHERE", LastSql, StringComparison.Ordinal); // ...but no WHERE in the SQL
        Assert.Equal(12, _db.ChangeTracker.Entries().Count());           // every row came over
    }

    [Fact]
    public void ToQueryString_shows_the_SQL_without_running_it()
    {
        var sql = Queries.AtLeast(_db.Requests, 50_000m).ToQueryString();
        Assert.Contains("FROM \"Requests\" AS \"r\"", sql, StringComparison.Ordinal);
        Assert.Contains("@threshold", sql, StringComparison.Ordinal);
    }

    [Fact]
    public async Task LeftJoin_becomes_LEFT_JOIN_and_keeps_Legal()
    {
        var rows = await Queries.DepartmentsWithRequests(_db).ToListAsync();

        Assert.Contains("LEFT JOIN \"Requests\"", LastSql, StringComparison.Ordinal);
        Assert.Contains(new DepartmentRow("Legal", null, null), rows);
        Assert.Equal(13, rows.Count);   // 12 requests + 1 department without any
    }

    [Fact]
    public async Task Gotcha_OrderBy_on_a_constructor_projected_record_is_not_translated()
    {
        var error = await Assert.ThrowsAsync<InvalidOperationException>(
            () => Queries.DepartmentsWithRequestsUntranslatable(_db).ToListAsync());
        Assert.Contains("could not be translated", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task Gotcha_a_CSharp_method_in_Where_throws_when_the_query_runs()
    {
        var query = Queries.StrategicUntranslatable(_db);   // building the query is fine...

        var error = await Assert.ThrowsAsync<InvalidOperationException>(() => query.ToListAsync());   // ...running it isn't
        Assert.Contains("could not be translated", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task The_fix_filters_in_SQL_then_applies_the_CSharp_rule_in_memory()
    {
        var strategic = await Queries.StrategicAsync(_db);

        Assert.Equal(["PR-2026-0103"], strategic.Select(r => r.Code));
        Assert.Contains("WHERE", LastSql, StringComparison.Ordinal);
    }

    [Fact]
    public async Task Gotcha_CountBy_compiles_on_a_DbSet_but_EF_Core_10_cannot_translate_it()
    {
        var error = await Assert.ThrowsAsync<InvalidOperationException>(
            () => Queries.CountByDepartmentUntranslatable(_db).ToListAsync());
        Assert.Contains("could not be translated", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task GroupBy_Count_is_the_database_version()
    {
        var counts = await Queries.CountByDepartment(_db).ToListAsync();

        Assert.Contains("GROUP BY \"r\".\"DepartmentCode\"", LastSql, StringComparison.Ordinal);
        Assert.Equal(Reports.CountByDepartmentInMemory(SampleData.Requests), counts);
    }

    [Fact]
    public async Task Same_report_from_SQLite_and_from_memory()
    {
        var fromDb = await _db.Requests.AsNoTracking().ToListAsync();
        Assert.Equal(Reports.TotalsByDepartment(SampleData.Requests), Reports.TotalsByDepartment(fromDb));
    }
}
